import React,{useState,useRef,useId} from 'react';
import {pair} from '../../../domain/story-relations.mjs';
const tones=['#5a7dd7','#229e8d','#aa77cf','#d19a4d','#cf7693','#638eae'];
export function RelationNetwork({overview,focusPair,onPair,onPerson,query='',large=false}){
 const instanceId=useId();
 const [zoom,setZoom]=useState(1),[offset,setOffset]=useState({x:0,y:0}),[focused,setFocused]=useState(null),pan=useRef(null),svg=useRef(null);
 const all=overview.allNodes,positions=new Map(all.map((p,i)=>{const angle=-Math.PI/2+i*Math.PI*2/Math.max(1,all.length),ring=all.length>12&&i%2?.7:1;return [p.id,{x:230+Math.cos(angle)*160*ring,y:170+Math.sin(angle)*112*ring,color:tones[i%tones.length]}];}));
 const names=id=>all.find(p=>p.id===id)?.name||'人物';
 const visibleRelations=overview.relations.filter(r=>!query||[names(r.from),names(r.to),r.name].join(' ').includes(query));
 const reset=()=>{setZoom(1);setOffset({x:0,y:0});setFocused(null);};
 return <div className={'u-relation-network '+(large?'large':'')}>
  <div className="u-network-tools"><span>{overview.nodes.filter(n=>n.active).length} 人已出现 · {overview.relations.filter(r=>overview.nodes.find(n=>n.id===r.from)?.active&&overview.nodes.find(n=>n.id===r.to)?.active).length} 条关系</span><div><button aria-label="缩小关系图" onClick={()=>setZoom(z=>Math.max(.6,z-.2))}>−</button><button aria-label="重置关系图" onClick={reset}>居中</button><button aria-label="放大关系图" onClick={()=>setZoom(z=>Math.min(2.6,z+.2))}>＋</button></div></div>
  <svg ref={svg} viewBox="0 0 460 340" role="group" aria-label="全局人物关系图，可拖动空白平移，点连线查看两人历程" onPointerDown={e=>{if(e.button!==0||e.target.closest('[data-graph-action]'))return;e.currentTarget.setPointerCapture(e.pointerId);pan.current={id:e.pointerId,x:e.clientX,y:e.clientY,offset};}} onPointerMove={e=>{const p=pan.current;if(!p||p.id!==e.pointerId)return;const scale=460/svg.current.getBoundingClientRect().width;setOffset({x:p.offset.x+(e.clientX-p.x)*scale,y:p.offset.y+(e.clientY-p.y)*scale});}} onPointerUp={()=>{pan.current=null;}} onPointerCancel={()=>{pan.current=null;}}>
   <g transform={'translate('+(230+offset.x)+' '+(170+offset.y)+') scale('+zoom+') translate(-230 -170)'}>
    {visibleRelations.map((r,i)=>{const a=positions.get(r.from),b=positions.get(r.to),key=pair(r.from,r.to),muted=focused&&!([r.from,r.to].includes(focused)),active=focusPair===key,mx=(a.x+b.x)/2,my=(a.y+b.y)/2;return <g key={key} className={'u-network-edge '+(r.planned?'planned ':'')+(active?'selected ':'')+(muted?'muted':'')} data-graph-action="edge" role="button" tabIndex={0} aria-label={names(r.from)+'与'+names(r.to)+'：'+r.name+'，查看两人历程'} onClick={()=>onPair(key)} onKeyDown={e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();onPair(key);}}}><title>{names(r.from)+' ↔ '+names(r.to)+' · '+r.name+(r.planned?'（计划）':r.evidence?'（正文已确认）':'（资料设定）')}</title><path className="u-network-line" d={'M '+a.x+' '+a.y+' L '+b.x+' '+b.y}/><path className="u-network-hit" d={'M '+a.x+' '+a.y+' L '+b.x+' '+b.y}/><rect x={mx-42} y={my-10} width="84" height="20" rx="10"/><text x={mx} y={my+3}>{r.name.length>8?r.name.slice(0,8)+'…':r.name}</text></g>;})}
    {overview.nodes.map(p=>{const at=positions.get(p.id),dim=query&&!p.name.includes(query)&&!visibleRelations.some(r=>r.from===p.id||r.to===p.id),clip=instanceId+'-person-'+p.id;return <g key={p.id} data-graph-action="person" className={'u-network-person '+(!p.active?'future ':'')+(dim?'muted ':'')+(focused===p.id?'focused':'')} role="button" tabIndex={0} aria-label={p.name+(p.active?'':'，尚未出现')+'，查看相关连线'} onClick={()=>setFocused(focused===p.id?null:p.id)} onDoubleClick={()=>onPerson?.(p.id)} onKeyDown={e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();setFocused(focused===p.id?null:p.id);}}}><title>{p.name+(p.active?' · 已到出场位置':' · 尚未到出场位置或未安排出场')}</title><circle className="u-network-halo" cx={at.x} cy={at.y} r="25" style={{stroke:at.color}}/><circle cx={at.x} cy={at.y} r="21" style={{fill:'color-mix(in srgb, '+at.color+' 15%, var(--cg-paper))'}}/>{p.avatarImage?<><defs><clipPath id={clip}><circle cx={at.x} cy={at.y} r="21"/></clipPath></defs><image href={p.avatarImage} x={at.x-21} y={at.y-21} width="42" height="42" preserveAspectRatio="xMidYMid slice" clipPath={'url(#'+clip+')'}/></>:<text className="u-network-initial" x={at.x} y={at.y+6}>{p.name.slice(0,1)}</text>}<rect className="u-network-name-bg" x={at.x-48} y={at.y+27} width="96" height="19" rx="5"/><text className="u-network-name" x={at.x} y={at.y+40}>{p.name.length>10?p.name.slice(0,10)+'…':p.name}</text></g>;})}
   </g>
  </svg>
  {overview.nodes.length===0&&<p className="u-network-empty">此刻还没有人物出场<br/>向后拖动时间指针，或切换“全部人物”。</p>}
  <div className="u-network-legend"><span>实线 · 设定／已确认</span><span>┄ 计划变化</span>{focused&&<button onClick={()=>onPerson?.(focused)}>查看 {names(focused)} 资料 ↗</button>}</div>
 </div>;
}

